        public static void Tick()
        {
            if (gaveUp) return;
            var now = DateTime.UtcNow;
            try
            {
                if (!isServer)
                {
                    if (now < nextProbe) return;
                    nextProbe = now.AddSeconds(5);
                    if (++probes > 720) { gaveUp = true; return; }   // ~1 hour: this is a player's game, not the server
                    if (!Probe()) return;
                }
                if (now >= nextCmd) { nextCmd = now.AddSeconds(1); ProcessCommands(); SyncBans(false); LoadCfg(); }
                if (now >= nextSnap) { nextSnap = now.AddSeconds(3); Snapshot(); }
                if (knownDirty && now >= nextKnownSave) { nextKnownSave = now.AddSeconds(30); SaveKnown(); }
                errors = 0;
            }
            catch (Exception e)
            {
                if (++errors <= 20) Log.W("AdminHost.Tick: " + e);
                if (errors > 200) { gaveUp = true; Log.W("AdminHost stopped after repeated errors"); }
            }
        }

