        // ------------------------------------------------------------------ commands from the Studio
        static void ProcessCommands()
        {
            if (!Directory.Exists(CmdDir)) return;
            foreach (var f in Directory.GetFiles(CmdDir, "*.json").OrderBy(x => x, StringComparer.Ordinal).Take(20))
            {
                Dictionary<string, object> c = null;
                try { c = Mj.Parse(File.ReadAllText(f, Encoding.UTF8)) as Dictionary<string, object>; }
                catch (IOException) { continue; }   // still being written
                catch (Exception e) { Log.W("bad command file " + f + ": " + e.Message); }
                try { File.Move(f, Path.Combine(CmdDir, "done", Path.GetFileName(f))); } catch { try { File.Delete(f); } catch { } }
                if (c == null) continue;
                Execute(c);
            }
        }

        static void Execute(Dictionary<string, object> c)
        {
            var id = Mj.S(c, "id", ""); var by = Mj.S(c, "by", "owner"); var byName = Mj.S(c, "byName", "المالك");
            var action = Mj.S(c, "action", ""); var target = Mj.S(c, "target", ""); var reason = Mj.S(c, "reason", "");
            var tname = target.Length > 0 ? KnownName(target) : "";
            bool ok = false; string output;
            try
            {
                switch (action)
                {
                    case "kick":
                        output = Kick(target, reason.Length > 0 ? reason : "اتطردت من السيرفر بواسطة الإدارة", out ok); break;
                    case "ban":
                        SyncBans(true);
                        output = banList == null ? "قايمة الحظر بتاعة Coop مش متاحة" : CheckBanned(target);
                        ok = banList != null && output.StartsWith("✓");
                        if (online.ContainsKey(target)) { bool k; Kick(target, "اتحظرت من السيرفر" + (reason.Length > 0 ? ": " + reason : ""), out k); output += " — واتطرد"; }
                        break;
                    case "unban":
                        SyncBans(true); ok = true; output = "✓ اتفك الحظر"; break;
                    case "run":
                        var cmd = Mj.S(c, "command", "");
                        var args = new List<string>();
                        object ao; if (c.TryGetValue("args", out ao) && ao is IEnumerable && !(ao is string)) foreach (var a in (IEnumerable)ao) args.Add(Convert.ToString(a, CultureInfo.InvariantCulture));
                        output = Run(cmd, args, out ok);
                        if (target.Length > 0) ignoreUntil[target] = DateTime.UtcNow.AddSeconds(60);
                        action = "run:" + cmd;
                        break;
                    case "refresh-catalog":
                        WriteCatalog(); ok = true; output = "✓"; break;
                    default:
                        output = "أمر مش معروف: " + action; break;
                }
            }
            catch (Exception e) { output = "خطأ: " + (e.InnerException ?? e).Message; ok = false; }
            Audit(by, byName, action, target, tname, reason, ok, output, id, c);
        }

        static string Kick(string cid, string reason, out bool ok)
        {
            ok = false;
            var peer = Peer(cid);
            if (peer == null) return "اللاعب مش أونلاين";
            try
            {
                var m = terminator.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "Disconnect" && x.GetParameters().Length == 2);
                if (m == null) throw new MissingMethodException("Disconnect");
                m.Invoke(terminator, new[] { peer, reason });
            }
            catch (Exception e)
            {   // fall back to the network peer itself
                Log.W("kick via terminator failed: " + (e.InnerException ?? e).Message);
                var d = peer.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(x => x.Name == "Disconnect" && x.GetParameters().Length == 0);
                if (d == null) return "مقدرتش أطرده: " + (e.InnerException ?? e).Message;
                d.Invoke(peer, null);
            }
            ok = true; return "✓ اتطرد";
        }

        static string Run(string cmd, List<string> args, out bool ok)
        {
            ok = false;
            if (dispatcher == null) return "أوامر Coop مش متاحة";
            var ready = dispatcher.GetType().GetMethod("EnsureReady", All);
            if (ready != null) ready.Invoke(dispatcher, null);
            var ex = dispatcher.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "Execute" && x.GetParameters().Length == 2);
            var r = ex.Invoke(dispatcher, new object[] { cmd, args });
            var found = Get(r, "Found"); var succ = Get(r, "Succeeded"); var outp = Str(Get(r, "Output")); var err = Str(Get(r, "ErrorCode"));
            if (found is bool && !(bool)found) return "الأمر مش موجود: " + cmd;
            ok = succ is bool ? (bool)succ : err.Length == 0;
            return (ok ? "✓ " : "✗ ") + outp + (err.Length > 0 ? " [" + err + "]" : "");
        }

        static void WriteCatalog()
        {
            try
            {
                var list = new List<object>();
                var descs = new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
                var cmds = registry == null ? null : Get(registry, "Commands") as IEnumerable;
                if (cmds != null)
                    foreach (var c in cmds)
                    {
                        var d = new Dictionary<string, object>();
                        var pre = Str(Get(c, "Prefix")); var nm = Str(Get(c, "Name"));
                        d["name"] = pre.Length > 0 ? pre + "." + nm : nm; d["description"] = Str(Get(c, "Description")); d["side"] = Str(Get(c, "Side"));
                        var al = new List<object>();
                        var ea = Get(c, "ExpectedArgs") as IEnumerable;
                        if (ea != null) foreach (var a in ea)
                            {
                                var ad = new Dictionary<string, object>();
                                foreach (var pi in a.GetType().GetProperties(BindingFlags.Instance | BindingFlags.Public)) { try { var v = pi.GetValue(a, null); if (v == null || v is string || v.GetType().IsPrimitive || v is Enum) ad[pi.Name] = v == null ? "" : Convert.ToString(v, CultureInfo.InvariantCulture); } catch { } }
                                ad["text"] = Convert.ToString(a);
                                al.Add(ad);
                            }
                        d["args"] = al;
                        descs[Convert.ToString(d["name"])] = d;
                    }
                var names = new List<string>();
                if (dispatcher != null)
                {
                    var gn = dispatcher.GetType().GetMethod("GetCommandNames", All);
                    var ready = dispatcher.GetType().GetMethod("EnsureReady", All);
                    if (ready != null) ready.Invoke(dispatcher, null);
                    var n = gn == null ? null : gn.Invoke(dispatcher, null) as IEnumerable;
                    if (n != null) foreach (var x in n) names.Add(Convert.ToString(x));
                }
                foreach (var n in names.Count > 0 ? names : descs.Keys.ToList())
                {
                    Dictionary<string, object> d;
                    if (!descs.TryGetValue(n, out d)) { d = new Dictionary<string, object>(); d["name"] = n; d["description"] = ""; d["args"] = new List<object>(); }
                    else d["name"] = n;
                    list.Add(d);
                }
                var root = new Dictionary<string, object>(); root["updated"] = Iso(DateTime.Now); root["commands"] = list;
                WriteJson(Path.Combine(StateDir, "catalog.json"), root);
            }
            catch (Exception e) { Log.W("catalog: " + (e.InnerException ?? e).Message); }
        }

        // ------------------------------------------------------------------ bans (our list -> Coop's Steam ban file)
        static List<string> BannedIds()
        {
            var d = ReadJson(Path.Combine(Root, "bans.json"));
            var r = new List<string>();
            object o; if (d.TryGetValue("bans", out o) && o is IEnumerable)
                foreach (var b in (IEnumerable)o) { var bd = b as Dictionary<string, object>; var id = bd == null ? "" : Mj.S(bd, "controllerId", ""); if (id.Length > 0 && !r.Contains(id)) r.Add(id); }
            return r;
        }

        static void SyncBans(bool force)
        {
            var f = Path.Combine(Root, "bans.json");
            var stamp = File.Exists(f) ? File.GetLastWriteTimeUtc(f) : DateTime.MinValue;
            if (!force && stamp == bansStamp) return;
            bansStamp = stamp;
            var ids = BannedIds();
            WriteBanFile(ids, banFormat);
            // make sure Coop really reads our file; if not, try the other shapes once and remember the one that works
            if (ids.Count > 0 && banList != null && !IsBanned(ids[0]))
                foreach (var fmt in new[] { "object", "list", "objects" })
                {
                    WriteBanFile(ids, fmt);
                    if (IsBanned(ids[0])) { banFormat = fmt; try { File.WriteAllText(Path.Combine(StateDir, "ban-format.txt"), fmt); } catch { } WriteServerState(); Log.W("ban file format: " + fmt); break; }
                }
            foreach (var id in ids) if (online.ContainsKey(id)) { bool k; Kick(id, "اتحظرت من السيرفر", out k); }
        }

        static void WriteBanFile(List<string> ids, string fmt)
        {
            if (string.IsNullOrEmpty(banPath)) return;
            object body;
            if (fmt == "list") body = ids.Cast<object>().ToList();
            else if (fmt == "objects") body = ids.Select(x => { var d = new Dictionary<string, object>(); d["steamId"] = x; return (object)d; }).ToList();
            else { var d = new Dictionary<string, object>(); d["steamIds"] = ids.Cast<object>().ToList(); body = d; }
            try { Directory.CreateDirectory(Path.GetDirectoryName(banPath)); WriteJson(banPath, body); }
            catch (Exception e) { Log.W("ban file: " + e.Message); }
        }

        static bool IsBanned(string id)
        {
            try
            {
                System.Threading.Thread.Sleep(30);   // the reload looks at the file time
                var m = banList.GetType().GetMethod("IsBanned", All);
                return m != null && (bool)m.Invoke(banList, new object[] { id });
            }
            catch { return false; }
        }
        static string CheckBanned(string id) { return IsBanned(id) ? "✓ اتحظر (Coop أكّد إنه هيترفض)" : "⚠ اتسجل في القايمة بس Coop لسه ما أكّدش الحظر"; }

        // ------------------------------------------------------------------ settings from the Studio
        static void LoadCfg()
        {
            var f = Path.Combine(Root, "admin-config.json");
            var st = File.Exists(f) ? File.GetLastWriteTimeUtc(f) : DateTime.MinValue;
            if (st == cfgStamp) return; cfgStamp = st;
            var d = ReadJson(f); var c = Mj.D(d, "cheats");
            cfg = new AdminCfg
            {
                CheatsEnabled = Mj.B(c, "enabled", true), SameIpAlert = Mj.B(c, "sameIp", true),
                GoldPerMin = Mj.N(c, "goldPerMin", 100000), RenownPerMin = Mj.N(c, "renownPerMin", 300), TroopsPerMin = Mj.N(c, "troopsPerMin", 150),
                SkillsPerMin = Mj.N(c, "skillsPerMin", 60), SettlementsPerMin = Mj.N(c, "settlementsPerMin", 2)
            };
        }

        // ------------------------------------------------------------------ audit log
        static void Audit(string by, string byName, string action, string target, string targetName, string reason, bool ok, string output, string id = "", Dictionary<string, object> cmd = null)
        {
            var d = new Dictionary<string, object>();
            d["time"] = Iso(DateTime.Now); d["id"] = id; d["by"] = by; d["byName"] = byName; d["action"] = action;
            d["target"] = target; d["targetName"] = targetName; d["reason"] = reason; d["ok"] = ok; d["output"] = output ?? "";
            if (cmd != null) { object a; if (cmd.TryGetValue("args", out a)) d["args"] = a; object l; if (cmd.TryGetValue("label", out l)) d["label"] = l; }
            AppendLine(Path.Combine(Root, "audit.jsonl"), d);
        }

        // ------------------------------------------------------------------ small helpers
        public static object Get(object o, string name)
        {
            if (o == null) return null;
            var t = o as Type ?? o.GetType(); var inst = o is Type ? null : o;
            for (var x = t; x != null; x = x.BaseType)
            {
                var p = x.GetProperty(name, All | BindingFlags.DeclaredOnly);
                if (p != null && p.GetIndexParameters().Length == 0) { try { return p.GetValue(inst, null); } catch { return null; } }
                var f = x.GetField(name, All | BindingFlags.DeclaredOnly);
                if (f != null) { try { return f.GetValue(inst); } catch { return null; } }
            }
            return null;
        }
        static string Str(object o) { return o == null ? "" : Convert.ToString(o, CultureInfo.InvariantCulture); }
        static double Num(object o) { try { return o == null ? 0 : Convert.ToDouble(o, CultureInfo.InvariantCulture); } catch { return 0; } }
        static bool IsSteam64(string s) { ulong v; return s != null && s.Length == 17 && s.StartsWith("7656") && ulong.TryParse(s, out v); }
        static string Iso(DateTime t) { return t.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture); }

        static Dictionary<string, object> ReadJson(string path)
        {
            try { if (File.Exists(path)) return Mj.Parse(File.ReadAllText(path, Encoding.UTF8)) as Dictionary<string, object> ?? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase); }
            catch (Exception e) { Log.W("read " + path + ": " + e.Message); }
            return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        }
        static void WriteJson(string path, object o)
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path));
                var tmp = path + ".tmp";
                File.WriteAllText(tmp, Jw.Write(o), new UTF8Encoding(false));
                if (File.Exists(path)) File.Replace(tmp, path, null); else File.Move(tmp, path);
            }
            catch (Exception e) { Log.W("write " + path + ": " + e.Message); }
        }
        static void AppendLine(string path, object o)
        {
            try { Directory.CreateDirectory(Path.GetDirectoryName(path)); File.AppendAllText(path, Jw.Write(o) + "\n", new UTF8Encoding(false)); }
            catch (Exception e) { Log.W("append " + path + ": " + e.Message); }
        }
    }

    // ---------------------------------------------------------------- tiny JSON writer (one line)
    public static class Jw
    {
        public static string Write(object o) { var sb = new StringBuilder(); W(sb, o); return sb.ToString(); }
        static void W(StringBuilder sb, object o)
        {
            if (o == null) { sb.Append("null"); return; }
            if (o is string) { S(sb, (string)o); return; }
            if (o is bool) { sb.Append((bool)o ? "true" : "false"); return; }
            if (o is IDictionary<string, object>)
            {
                sb.Append('{'); bool first = true;
                foreach (var kv in (IDictionary<string, object>)o) { if (!first) sb.Append(','); first = false; S(sb, kv.Key); sb.Append(':'); W(sb, kv.Value); }
                sb.Append('}'); return;
            }
            if (o is IEnumerable)
            {
                sb.Append('['); bool first = true;
                foreach (var x in (IEnumerable)o) { if (!first) sb.Append(','); first = false; W(sb, x); }
                sb.Append(']'); return;
            }
            if (o is double || o is float || o is decimal) { var d = Convert.ToDouble(o); sb.Append(double.IsNaN(d) || double.IsInfinity(d) ? "0" : d.ToString("0.######", CultureInfo.InvariantCulture)); return; }
            if (o.GetType().IsPrimitive) { sb.Append(Convert.ToString(o, CultureInfo.InvariantCulture)); return; }
            S(sb, Convert.ToString(o, CultureInfo.InvariantCulture));
        }
        static void S(StringBuilder sb, string s)
        {
            sb.Append('"');
            foreach (var c in s)
            {
                if (c == '"') sb.Append("\\\""); else if (c == '\\') sb.Append("\\\\");
                else if (c == '\n') sb.Append("\\n"); else if (c == '\r') sb.Append("\\r"); else if (c == '\t') sb.Append("\\t");
                else if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                else sb.Append(c);
            }
            sb.Append('"');
        }
    }
