{
    public static class RulesGate
    {
        public static bool Enabled
        {
            get
            {
                try
                {
                    var dir = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location), "..", "..", "aurelion"));
                    var f = Path.Combine(dir, "rules.json");
                    if (!File.Exists(f)) return false;
                    var d = Mj.Parse(File.ReadAllText(f, Encoding.UTF8)) as System.Collections.Generic.Dictionary<string, object>;
